fn ready_push(loop_: &V, h: V) -> R {
    let ready = getattr(loop_, "_ready")?;
    match &ready {
        V::Deque(d) => { let mut d = d.borrow_mut(); if d.max.is_none() { d.v.push_back(h); return Ok(V::None); } }
        _ => {}
